# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

def _name_key(student: Student) -> Tuple[str, str]:
    last = student.last_name.casefold()
    first = student.first_name.casefold()
    return (last, first)

def _label(student: Student) -> str:
    return f"{student.display_name} ({student.student_id})"

def _check_roster(roster: List[Student]) -> None:
    """Reject an empty roster or any missing email."""
    if not roster:
        raise ValueError("no students given")
    for student in roster:
        if not student.email:
            label = _label(student)
            raise ValueError(f"no email for {label}")

def _column_widths(
    roster: List[Student]
) -> Tuple[int, int]:
    names = [item.display_name for item in roster]
    sections = [item.section for item in roster]
    return max(map(len, names)), max(map(len, sections))

def _format_row(
    student: Student, widths: Tuple[int, int]
) -> str:
    name_width, section_width = widths
    name = student.display_name.ljust(name_width)
    section = student.section.ljust(section_width)
    return f"{name}  {section}  {student.email}"

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Sorted contact rows, one per student."""
    roster = sorted(students, key=_name_key)
    _check_roster(roster)
    widths = _column_widths(roster)
    return [_format_row(item, widths) for item in roster]
